output_text:
[
  {
    "id": "no_cart_single_file",
    "text": "Shopping carts must not be taken into single-file aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "cartInSingleFileAisle": {
          "and": [
            "hasCart",
            "singleFileAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartInSingleFileAisle"
    }
  },
  {
    "id": "park_cart_at_narrow_mouth",
    "text": "A shopper pushing a cart must park it at the wide mouth of the single-file shelf aisle before proceeding into that aisle.",
    "abstraction": {
      "state_properties": {
        "narrowAisleMouth": {
          "and": [
            "at(6,3)",
            {
              "ge": [
                "freeWidthH",
                12
              ]
            }
          ]
        },
        "cartAtNarrowAisleMouth": {
          "and": [
            "narrowAisleMouth",
            "hasCart"
          ]
        }
      },
      "events": {
        "cartDrop": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartAtNarrowAisleMouth",
      "discharge": "cartDrop"
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "If a shopper parks or releases a cart inside the store, they must retrieve it before leaving.",
    "abstraction": {
      "state_properties": {
        "withoutCart": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartDrop": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": "withoutCart"
        },
        "cartRetrieve": {
          "pre": {
            "and": [
              "withoutCart",
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartDrop",
      "discharge": "cartRetrieve"
    }
  },
  {
    "id": "wide_shelf_requires_cart",
    "text": "Items on shelves accessible from a wide aisle must not be handled unless the shopper has a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "wideShelfAccess": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileAisle"
            }
          ]
        },
        "withoutCart": {
          "not": "hasCart"
        }
      },
      "events": {
        "shelfInteraction": {
          "pre": {
            "and": [
              "INTERACT",
              "adjShelf"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "shelfInteraction",
          "wideShelfAccess",
          "withoutCart"
        ]
      }
    }
  },
  {
    "id": "no_cart_side_shelf_service",
    "text": "A shopper must not interact with side-facing shelves while holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "sideFacingShelfAccess": {
          "and": [
            "adjShelf",
            {
              "or": [
                "shelfE",
                "shelfW"
              ]
            }
          ]
        }
      },
      "events": {
        "shelfInteraction": {
          "pre": {
            "and": [
              "INTERACT",
              "adjShelf"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "sideFacingShelfAccess",
          "shelfInteraction"
        ]
      }
    }
  },
  {
    "id": "one_way_cart_flow",
    "text": "Carts in wide horizontal shopping aisles must follow the one-way eastbound flow and not move west.",
    "abstraction": {
      "state_properties": {
        "wideHorizontalAisle": {
          "ge": [
            "freeWidthH",
            12
          ]
        },
        "cartInWideHorizontalAisle": {
          "and": [
            "hasCart",
            "wideHorizontalAisle"
          ]
        }
      },
      "events": {
        "cartMovesWestInWideAisle": {
          "pre": {
            "and": [
              "cartInWideHorizontalAisle",
              "W"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartMovesWestInWideAisle"
    }
  },
  {
    "id": "avoid_checkout_lane_transit",
    "text": "After shopping, carts should not be pushed along the front checkout corridor except at the exit cell itself.",
    "abstraction": {
      "state_properties": {
        "checkoutLaneBeforeExit": {
          "or": [
            "at(7,7)",
            "at(8,7)",
            "at(9,7)",
            "at(10,7)"
          ]
        }
      },
      "events": {
        "cartTransitInCheckoutLane": {
          "pre": {
            "and": [
              "hasCart",
              "checkoutLaneBeforeExit",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartTransitInCheckoutLane"
    }
  },
  {
    "id": "descend_at_right_wall",
    "text": "On the final exit approach aisle, a cart should continue to the right wall before descending into the exit row.",
    "abstraction": {
      "state_properties": {
        "finalExitAisleBeforeWall": {
          "and": [
            "at(10,6)",
            "hasCart"
          ]
        },
        "rightWallExitAisle": {
          "and": [
            "at(11,6)",
            "hasCart"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": "finalExitAisleBeforeWall",
      "discharge": "rightWallExitAisle"
    }
  }
]
